package com.bplus.share;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;import java.util.*;
/** Explicit target picker shared by single-file and selected-message forwarding. */
public final class ForwardAction{
 public static void one(Activity a,JSONObject m){ArrayList<JSONObject> messages=new ArrayList<>();messages.add(m);show(a,messages,()->{});}
 public static void show(Activity a,ArrayList<JSONObject> input,Runnable done){ArrayList<JSONObject> messages=new ArrayList<>();for(JSONObject m:input){if(m.optString("kind").equals("deleted"))continue;if(m.optString("kind").equals("file")&&!FileCards.available(a,m)){new AppDialog(a).setMessage(a.getString(R.string.file_unavailable)+"\n"+m.optString("name")).setPositiveButton(android.R.string.ok,null).show();return;}messages.add(m);}if(messages.isEmpty())return;
 ArrayList<JSONObject> targets=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();JSONArray groups=LocalGroups.all();for(int i=0;i<groups.length();i++){JSONObject g=groups.optJSONObject(i);if(g==null||g.optBoolean("deleted")||!g.optBoolean("joined"))continue;try{targets.add(new JSONObject(g.toString()).put("forwardGroup",true));labels.add(a.getString(R.string.share_group_target,g.optString("name")));}catch(Exception ignored){}}JSONArray peers=Store.peers();for(int i=0;i<peers.length();i++){JSONObject p=peers.optJSONObject(i);if(p==null)continue;targets.add(p);labels.add(p.optString("name"));}
 if(targets.isEmpty()){Toast.makeText(a,R.string.no_chats,1).show();return;}new AppDialog(a).setTitle(R.string.forward_file).setItems(labels.toArray(new String[0]),(dialog,index)->{JSONObject target=targets.get(index);new AppDialog(a).setTitle(R.string.forward_file).setMessage(a.getString(R.string.send_items_confirm,messages.size(),labels.get(index))).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.send_now,(confirm,which)->{new Thread(()->{int ok=0;String error="";for(JSONObject m:messages)try{boolean file=m.optString("kind").equals("file");if(target.optBoolean("forwardGroup")){JSONObject g=LocalGroups.get(target.optString("id"));if(g==null||g.optBoolean("deleted")||!g.optBoolean("joined"))throw new java.io.IOException("Group unavailable");if(file)LocalGroups.sendFile(g.optString("id"),FileCards.uri(m),m.optString("name"),m.optLong("size"));else LocalGroups.sendText(g.optString("id"),m.optString("body"));ok++;}else{JSONObject p=Store.peerById(target.optString("id"));if(p==null)throw new java.io.IOException("Device no longer paired");boolean sent=file?TransferService.sendToPeer(p,FileCards.uri(m),m.optString("name"),m.optLong("size")):TransferService.sendTextToPeer(p,m.optString("body"));if(sent)ok++;}}catch(Exception e){error=e.getMessage();}final int count=ok;final String reason=error;a.runOnUiThread(()->{done.run();Toast.makeText(a,a.getString(R.string.send_items_result,count,messages.size())+(reason.isEmpty()?"":"\n"+reason),1).show();});}).start();}).show();}).show();
 }
}
